(function(){"use strict";const V="12.0.3-CONFIDENCE-SYNC";function panel(m,e){let p=document.getElementById("fatalDiagnostic");if(!p){p=document.createElement("section");p.id="fatalDiagnostic";p.style.cssText="margin:14px;padding:14px;border:2px solid #ff6b78;border-radius:14px;background:#321218;color:#ffe8ea;font-family:monospace;white-space:pre-wrap;word-break:break-word";document.body.prepend(p)}p.textContent+=(p.textContent?"\n\n":"")+"❌ "+m+(e?"\n"+(e.name||"Error")+": "+(e.message||String(e))+"\n"+(e.stack||""):"")}async function start(){try{if("caches" in window){for(const n of await caches.keys())if(!n.includes(V))await caches.delete(n)}const u=new URL("./app.js",document.baseURI);u.searchParams.set("v",V);u.searchParams.set("t",Date.now());const r=await fetch(u.href,{cache:"no-store"});if(!r.ok)throw new Error("app.js: HTTP "+r.status);await import(u.href);console.log("V12.0.3-CONFIDENCE-SYNC iniciado") }catch(e){panel("No se pudo cargar app.js desde la misma carpeta de index.html.",e)}}window.addEventListener("error",e=>panel("Error global en "+(e.filename?e.filename.split("/").pop():"archivo desconocido")+", línea "+(e.lineno||"?")+".",e.error||new Error(e.message||"Error desconocido")));window.addEventListener("unhandledrejection",e=>panel("Promesa rechazada.",e.reason instanceof Error?e.reason:new Error(String(e.reason||"Sin detalle"))));document.readyState==="loading"?document.addEventListener("DOMContentLoaded",start,{once:true}):start()})();
